/* 1. Validate Configuration */
int config_valid = TRUE32;
if ((ig_config.accept_threshold >= ig_config.reject_threshold) ||
    (ig_config.max_consecutive_reject < 1U) ||
    (ig_config.max_consecutive_reject > 20U)) {
    config_valid = FALSE32;
}

/* 2. Validate Inputs: Non-NULL, Finite, Variance > 0 */
int input_valid = TRUE32;
if (ig_input.residual == NULL || ig_input.variance == NULL) {
    input_valid = FALSE32;
} else if (!adcs_is_finite_vec3(ig_input.residual) || !adcs_is_finite_vec3(ig_input.variance)) {
    input_valid = FALSE32;
} else {
    for (int i = 0; i < 3; i++) {
        if (ig_input.variance->m[i][0] <= 0.0) {
            input_valid = FALSE32;
            break;
        }
    }
}

/* 3. Combine Validity */
int is_valid = (config_valid && input_valid);

/* 4. Check Enable Signal (Binary Requirement) */
unint32 enable_val = ig_input.enable;
int is_enabled = (enable_val == 1) ? 1 : 0;
int is_disabled = (enable_val == 0) ? 1 : 0;
int invalid_enable = (enable_val != 0 && enable_val != 1) ? 1 : 0;

/* 5. Handle Disable Case */
if (is_disabled) {
    ig_output.mode = IG_ACCEPT;
    ig_output.consecutive_reject = 0U;
    ig_output.nis = 0.0;
    ig_output.whitened_norm = 0.0;
    ig_output.use_measurement = 1;
    return;
}

/* 6. Handle Invalid Inputs or Invalid Enable -> FAULT */
if (!is_valid || invalid_enable) {
    ig_output.mode = IG_FAULT;
    ig_output.nis = INFINITY;
    ig_output.whitened_norm = INFINITY;
    ig_output.use_measurement = 0;
    return;
}

/* 7. Compute Whitened Vector */
adcs_vec3_t whitened = {{0, 0, 0}};
int whitening_success = TRUE32;
for (int i = 0; i < 3; i++) {
    double var = ig_input.variance->m[i][0];
    double res = ig_input.residual->m[i][0];
    double sqrt_var = sqrt(var);

    if (!isfinite(sqrt_var) || sqrt_var == 0.0) {
        whitening_success = FALSE32;
        break;
    }
    whitened.m[i][0] = res / sqrt_var;
}

if (!whitening_success) {
    ig_output.mode = IG_FAULT;
    ig_output.nis = INFINITY;
    ig_output.whitened_norm = INFINITY;
    ig_output.use_measurement = 0;
    return;
}

/* 8. Compute NIS */
double nis = adcs_vec3_dot(&whitened, &whitened);
ig_output.whitened_norm = sqrt(nis);

/* 9. State Transition Logic */
switch (ig_state.mode) {
    case IG_ACCEPT:
        if (nis <= ig_config.accept_threshold) {
            ig_output.mode = IG_ACCEPT;
            ig_output.consecutive_reject = 0U;
        } else if (nis < ig_config.reject_threshold) {
            /* Preserve ACCEPT */
            ig_output.mode = IG_ACCEPT;
            ig_output.consecutive_reject = 0U;
        } else {
            /* Transition to REJECT */
            ig_output.mode = IG_REJECT;
            ig_output.consecutive_reject = 1U;
        }
        break;

    case IG_REJECT:
        if (nis <= ig_config.accept_threshold) {
            /* Reset to ACCEPT */
            ig_output.mode = IG_ACCEPT;
            ig_output.consecutive_reject = 0U;
        } else {
            /* Preserve REJECT (both middle and high bands) */
            ig_output.mode = IG_REJECT;
            ig_output.consecutive_reject = ig_output.consecutive_reject + 1U;
            if (ig_output.consecutive_reject > ig_config.max_consecutive_reject) {
                ig_output.consecutive_reject = ig_config.max_consecutive_reject;
            }
        }
        break;

    case IG_FAULT:
    default:
        /* Fault latches */
        ig_output.mode = IG_FAULT;
        /* Retain count */
        break;
}

/* 10. Check for Fault Threshold Exceeded */
if (ig_output.mode == IG_REJECT && 
    ig_output.consecutive_reject >= ig_config.max_consecutive_reject) {
    ig_output.mode = IG_FAULT;
    /* Retain count */
}

/* 11. Finalize Outputs */
ig_output.nis = nis;
ig_output.use_measurement = (ig_output.mode == IG_ACCEPT) ? 1 : 0;

